import random
from typing import List, Dict

class AI:
    def __init__(self):
        self.knowledge = {
            "greetings": ["Hello", "Hi", "Hey"],
            "goodbyes": ["Bye", "See you later", "Have a great day"],
            "responses": [
                "I'm happy to help!",
                "What can I assist you with?",
                "Please go ahead and ask your question.",
            ],
        }
        self.responses = {
            "greetings": random.choice(self.knowledge["greetings"]),
            "goodbyes": random.choice(self.knowledge["goodbyes"]),
            "responses": random.choice(self.knowledge["responses"]),
        }

    def respond_to_greeting(self, message: str) -> str:
        """Responds to a greeting."""
        if self.match_message(message, "greetings"):
            return self.responses
